  1	package com.loja.api.controllers;
  2	
  3	import com.google.gson.Gson;
  4	import com.google.gson.GsonBuilder;
  5	import com.loja.api.dto.*;
  6	import com.loja.domain.entities.*;
  7	import com.loja.domain.strategies.shipping.ShippingUnavailableException;
  8	import com.loja.repositories.CustomerRepository;
  9	import com.loja.repositories.NotificationRepository;
 10	import com.loja.repositories.OrderRepository;
 11	import com.loja.repositories.ProductRepository;
 12	import com.loja.services.CheckoutService;
 13	import com.loja.services.OrderService;
 14	import com.loja.services.ValidationService;
 15	import io.javalin.Javalin;
 16	import io.javalin.http.Context;
 17	
 18	import java.time.Instant;
 19	import java.time.format.DateTimeFormatter;
 20	import java.util.List;
 21	import java.util.stream.Collectors;
 22	
 23	public class ApiController {
 24	    private final Gson gson;
 25	    private final CheckoutService checkoutService;
 26	    private final OrderService orderService;
 27	    private final ValidationService validationService;
 28	    private final ProductRepository productRepository;
 29	    private final CustomerRepository customerRepository;
 30	    private final NotificationRepository notificationRepository;
 31	    private final OrderRepository orderRepository;
 32	
 33	    public ApiController(
 34	            CheckoutService checkoutService,
 35	            OrderService orderService,
 36	            ValidationService validationService,
 37	            ProductRepository productRepository,
 38	            CustomerRepository customerRepository,
 39	            NotificationRepository notificationRepository,
 40	            OrderRepository orderRepository) {
 41	        this.gson = new GsonBuilder().setPrettyPrinting().create();
 42	        this.checkoutService = checkoutService;
 43	        this.orderService = orderService;
 44	        this.validationService = validationService;
 45	        this.productRepository = productRepository;
 46	        this.customerRepository = customerRepository;
 47	        this.notificationRepository = notificationRepository;
 48	        this.orderRepository = orderRepository;
 49	    }
 50	
 51	    public void registerRoutes(Javalin app) {
 52	        app.post("/checkout/summary", this::calculateSummary);
 53	        app.post("/orders", this::createOrder);
 54	        app.get("/orders/{id}", this::getOrder);
 55	        app.post("/orders/{id}/payment", this::confirmPayment);
 56	        app.post("/orders/{id}/shipment", this::shipOrder);
 57	        app.post("/orders/{id}/delivery", this::deliverOrder);
 58	        app.post("/orders/{id}/cancellation", this::cancelOrder);
 59	        app.get("/products/{sku}", this::getProduct);
 60	        app.get("/customers/{cpf}", this::getCustomer);
 61	        app.get("/customers/{cpf}/notifications", this::getNotifications);
 62	        app.post("/notifications/{id}/read", this::markNotificationAsRead);
 63	    }
 64	
 65	    private void calculateSummary(Context ctx) {
 66	        try {
 67	            CheckoutRequestDto dto = gson.fromJson(ctx.body(), CheckoutRequestDto.class);
 68	            CheckoutService.CheckoutRequest request = parseCheckoutRequest(dto);
 69	
 70	            validationService.validateCheckoutRequest(request);
 71	            OrderSummary summary = checkoutService.calculateSummary(request);
 72	
 73	            ctx.status(200).json(toSummaryDto(summary));
 74	
 75	        } catch (ValidationService.ValidationException e) {
 76	            handleValidationError(ctx, e);
 77	        } catch (ShippingUnavailableException e) {
 78	            ctx.status(503).json(new ErrorResponseDto("CARRIER_UNAVAILABLE"));
 79	        } catch (Exception e) {
 80	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
 81	        }
 82	    }
 83	
 84	    private void createOrder(Context ctx) {
 85	        try {
 86	            CheckoutRequestDto dto = gson.fromJson(ctx.body(), CheckoutRequestDto.class);
 87	            CheckoutService.CheckoutRequest request = parseCheckoutRequest(dto);
 88	
 89	            validationService.validateCheckoutRequest(request);
 90	            OrderSummary summary = checkoutService.calculateSummary(request);
 91	
 92	            List<OrderItem> items = dto.items.stream()
 93	                    .map(i -> new OrderItem(i.sku, i.quantity))
 94	                    .collect(Collectors.toList());
 95	
 96	            Order order = orderService.createOrder(
 97	                    dto.customer.cpf,
 98	                    dto.customer.email,
 99	                    items,
100	                    summary
101	            );
102	
103	            ctx.status(201).json(toOrderDto(order));
104	
105	        } catch (ValidationService.ValidationException e) {
106	            handleValidationError(ctx, e);
107	        } catch (ShippingUnavailableException e) {
108	            ctx.status(503).json(new ErrorResponseDto("CARRIER_UNAVAILABLE"));
109	        } catch (Exception e) {
110	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
111	        }
112	    }
113	
114	    private void getOrder(Context ctx) {
115	        try {
116	            String orderId = ctx.pathParam("id");
117	            Order order = orderRepository.findById(orderId);
118	
119	            if (order == null) {
120	                ctx.status(404).json(new ErrorResponseDto("ORDER_NOT_FOUND"));
121	                return;
122	            }
123	
124	            ctx.status(200).json(toOrderDto(order));
125	
126	        } catch (Exception e) {
127	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
128	        }
129	    }
130	
131	    private void confirmPayment(Context ctx) {
132	        try {
133	            String orderId = ctx.pathParam("id");
134	            PaymentRequestDto dto = gson.fromJson(ctx.body(), PaymentRequestDto.class);
135	
136	            if (dto.transactionId == null || dto.transactionId.isBlank() ||
137	                    dto.paidAt == null || dto.paidAt.isBlank()) {
138	                ctx.status(422).json(new ErrorResponseDto("INVALID_ORDER"));
139	                return;
140	            }
141	
142	            Instant paidAt = Instant.parse(dto.paidAt);
143	            Order order = orderService.confirmPayment(orderId, dto.transactionId, paidAt);
144	
145	            ctx.status(200).json(toOrderDto(order));
146	
147	        } catch (OrderService.OrderExpiredException e) {
148	            Order order = orderRepository.findById(ctx.pathParam("id"));
149	            ctx.status(409).json(new ErrorResponseDto("ORDER_EXPIRED"));
150	        } catch (OrderService.InsufficientStockException e) {
151	            ctx.status(409).json(new ErrorResponseDto("INSUFFICIENT_STOCK"));
152	        } catch (OrderService.PaymentException e) {
153	            if (e.getMessage().contains("not found")) {
154	                ctx.status(404).json(new ErrorResponseDto("ORDER_NOT_FOUND"));
155	            } else if (e.getMessage().contains("cannot be paid")) {
156	                ctx.status(409).json(new ErrorResponseDto("OPERATION_NOT_ALLOWED"));
157	            } else {
158	                ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
159	            }
160	        } catch (Exception e) {
161	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
162	        }
163	    }
164	
165	    private void shipOrder(Context ctx) {
166	        try {
167	            String orderId = ctx.pathParam("id");
168	            ShipmentRequestDto dto = gson.fromJson(ctx.body(), ShipmentRequestDto.class);
169	
170	            if (dto.trackingCode == null || dto.trackingCode.isBlank()) {
171	                ctx.status(422).json(new ErrorResponseDto("INVALID_ORDER"));
172	                return;
173	            }
174	
175	            Order order = orderService.shipOrder(orderId, dto.trackingCode);
176	            ctx.status(200).json(toOrderDto(order));
177	
178	        } catch (OrderService.ShipmentException e) {
179	            if (e.getMessage().contains("not found")) {
180	                ctx.status(404).json(new ErrorResponseDto("ORDER_NOT_FOUND"));
181	            } else {
182	                ctx.status(409).json(new ErrorResponseDto("OPERATION_NOT_ALLOWED"));
183	            }
184	        } catch (Exception e) {
185	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
186	        }
187	    }
188	
189	    private void deliverOrder(Context ctx) {
190	        try {
191	            String orderId = ctx.pathParam("id");
192	            Order order = orderService.deliverOrder(orderId);
193	            ctx.status(200).json(toOrderDto(order));
194	
195	        } catch (OrderService.DeliveryException e) {
196	            if (e.getMessage().contains("not found")) {
197	                ctx.status(404).json(new ErrorResponseDto("ORDER_NOT_FOUND"));
198	            } else {
199	                ctx.status(409).json(new ErrorResponseDto("OPERATION_NOT_ALLOWED"));
200	            }
201	        } catch (Exception e) {
202	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
203	        }
204	    }
205	
206	    private void cancelOrder(Context ctx) {
207	        try {
208	            String orderId = ctx.pathParam("id");
209	            Order order = orderService.cancelOrder(orderId);
210	            ctx.status(200).json(toOrderDto(order));
211	
212	        } catch (OrderService.CancellationException e) {
213	            if (e.getMessage().contains("not found")) {
214	                ctx.status(404).json(new ErrorResponseDto("ORDER_NOT_FOUND"));
215	            } else {
216	                ctx.status(409).json(new ErrorResponseDto("OPERATION_NOT_ALLOWED"));
217	            }
218	        } catch (Exception e) {
219	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
220	        }
221	    }
222	
223	    private void getProduct(Context ctx) {
224	        try {
225	            String sku = ctx.pathParam("sku");
226	            Product product = productRepository.findBySku(sku);
227	
228	            if (product == null) {
229	                ctx.status(404).json(new ErrorResponseDto("PRODUCT_NOT_FOUND"));
230	                return;
231	            }
232	
233	            ProductResponseDto dto = new ProductResponseDto();
234	            dto.sku = product.getSku();
235	            dto.name = product.getName();
236	            dto.price = product.getPrice().toDouble();
237	            dto.weightKg = product.getWeightKg();
238	            dto.stock = product.getStock();
239	            dto.discontinued = product.isDiscontinued();
240	
241	            ctx.status(200).json(dto);
242	
243	        } catch (Exception e) {
244	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
245	        }
246	    }
247	
248	    private void getCustomer(Context ctx) {
249	        try {
250	            String cpf = ctx.pathParam("cpf");
251	            Customer customer = customerRepository.findByCpf(cpf);
252	
253	            if (customer == null) {
254	                ctx.status(404).json(new ErrorResponseDto("CUSTOMER_NOT_FOUND"));
255	                return;
256	            }
257	
258	            CustomerResponseDto dto = new CustomerResponseDto();
259	            dto.cpf = customer.getCpf();
260	            dto.creditBalance = customer.getCreditBalance().toDouble();
261	
262	            ctx.status(200).json(dto);
263	
264	        } catch (Exception e) {
265	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
266	        }
267	    }
268	
269	    private void getNotifications(Context ctx) {
270	        try {
271	            String cpf = ctx.pathParam("cpf");
272	
273	            if (!customerRepository.exists(cpf)) {
274	                ctx.status(404).json(new ErrorResponseDto("CUSTOMER_NOT_FOUND"));
275	                return;
276	            }
277	
278	            List<Notification> notifications = notificationRepository.findByCustomerCpf(cpf);
279	            List<NotificationResponseDto> dtos = notifications.stream()
280	                    .map(n -> {
281	                        NotificationResponseDto dto = new NotificationResponseDto();
282	                        dto.id = n.getId();
283	                        dto.type = n.getType().name();
284	                        dto.orderId = n.getOrderId();
285	                        dto.status = n.getStatus().name();
286	                        return dto;
287	                    })
288	                    .collect(Collectors.toList());
289	
290	            ctx.status(200).json(dtos);
291	
292	        } catch (Exception e) {
293	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
294	        }
295	    }
296	
297	    private void markNotificationAsRead(Context ctx) {
298	        try {
299	            long notificationId = Long.parseLong(ctx.pathParam("id"));
300	            Notification notification = notificationRepository.findById(notificationId);
301	
302	            if (notification == null) {
303	                ctx.status(404).json(new ErrorResponseDto("NOTIFICATION_NOT_FOUND"));
304	                return;
305	            }
306	
307	            notification.markAsRead();
308	            notificationRepository.update(notification);
309	
310	            NotificationResponseDto dto = new NotificationResponseDto();
311	            dto.id = notification.getId();
312	            dto.type = notification.getType().name();
313	            dto.orderId = notification.getOrderId();
314	            dto.status = notification.getStatus().name();
315	
316	            ctx.status(200).json(dto);
317	
318	        } catch (NumberFormatException e) {
319	            ctx.status(404).json(new ErrorResponseDto("NOTIFICATION_NOT_FOUND"));
320	        } catch (Exception e) {
321	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
322	        }
323	    }
324	
325	    private CheckoutService.CheckoutRequest parseCheckoutRequest(CheckoutRequestDto dto) {
326	        List<OrderItem> items = dto.items.stream()
327	                .map(i -> new OrderItem(i.sku, i.quantity))
328	                .collect(Collectors.toList());
329	
330	        return new CheckoutService.CheckoutRequest(
331	                dto.customer.cpf,
332	                items,
333	                dto.zipCode,
334	                dto.region != null ? Region.valueOf(dto.region) : null,
335	                dto.shippingMethod != null ? ShippingMethod.valueOf(dto.shippingMethod) : null,
336	                dto.coupon != null && !dto.coupon.isBlank() ? CouponCode.valueOf(dto.coupon) : null,
337	                dto.paymentMethod != null ? PaymentMethod.valueOf(dto.paymentMethod) : null,
338	                dto.installments != null ? dto.installments : 1,
339	                dto.clubTier != null ? ClubTier.valueOf(dto.clubTier) : null
340	        );
341	    }
342	
343	    private SummaryResponseDto toSummaryDto(OrderSummary summary) {
344	        SummaryResponseDto dto = new SummaryResponseDto();
345	        dto.productsSubtotal = summary.getProductsSubtotal().toDouble();
346	        dto.couponDiscount = summary.getCouponDiscount().toDouble();
347	        dto.shippingCost = summary.getShippingCost().toDouble();
348	        dto.deliveryDays = summary.getDeliveryDays();
349	        dto.insurance = summary.getInsurance().toDouble();
350	        dto.paymentAdjustment = summary.getPaymentAdjustment().toDouble();
351	        dto.finalTotal = summary.getFinalTotal().toDouble();
352	        dto.installments = summary.getInstallments();
353	        dto.installmentAmount = summary.getInstallmentAmount().toDouble();
354	        dto.nextPurchaseCredit = summary.getNextPurchaseCredit().toDouble();
355	        dto.gift = summary.isGift();
356	        return dto;
357	    }
358	
359	    private OrderResponseDto toOrderDto(Order order) {
360	        OrderResponseDto dto = new OrderResponseDto();
361	        dto.id = order.getId();
362	        dto.status = order.getStatus().name();
363	        dto.createdAt = DateTimeFormatter.ISO_INSTANT.format(order.getCreatedAt());
364	        dto.summary = toSummaryDto(order.getSummary());
365	        dto.items = order.getItems().stream()
366	                .map(i -> {
367	                    OrderResponseDto.OrderItemResponseDto itemDto = new OrderResponseDto.OrderItemResponseDto();
368	                    itemDto.sku = i.getSku();
369	                    itemDto.quantity = i.getQuantity();
370	                    return itemDto;
371	                })
372	                .collect(Collectors.toList());
373	        dto.trackingCode = order.getTrackingCode();
374	        return dto;
375	    }
376	
377	    private void handleValidationError(Context ctx, ValidationService.ValidationException e) {
378	        int status = switch (e.getErrorCode()) {
379	            case "CARRIER_UNAVAILABLE" -> 503;
380	            default -> 422;
381	        };
382	        ctx.status(status).json(new ErrorResponseDto(e.getErrorCode()));
383	    }
384	}

