206	    private void cancelOrder(Context ctx) {
207	        try {
208	            String orderId = ctx.pathParam("id");
209	            Order order = orderService.cancelOrder(orderId);
210	            ctx.status(200).json(toOrderDto(order));
211	
212	        } catch (OrderService.CancellationException e) {
213	            if (e.getMessage().contains("not found")) {
214	                ctx.status(404).json(new ErrorResponseDto("ORDER_NOT_FOUND"));
215	            } else {
216	                ctx.status(409).json(new ErrorResponseDto("OPERATION_NOT_ALLOWED"));
217	            }
218	        } catch (Exception e) {
219	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
220	        }
221	    }
222	
223	    private void getProduct(Context ctx) {
224	        try {
225	            String sku = ctx.pathParam("sku");
226	            Product product = productRepository.findBySku(sku);
227	
228	            if (product == null) {
229	                ctx.status(404).json(new ErrorResponseDto("PRODUCT_NOT_FOUND"));
230	                return;
231	            }
232	
233	            ProductResponseDto dto = new ProductResponseDto();
234	            dto.sku = product.getSku();
235	            dto.name = product.getName();
236	            dto.price = product.getPrice().toDouble();
237	            dto.weightKg = product.getWeightKg();
238	            dto.stock = product.getStock();
239	            dto.discontinued = product.isDiscontinued();
240	
241	            ctx.status(200).json(dto);
242	
243	        } catch (Exception e) {
244	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
245	        }
246	    }
247	
248	    private void getCustomer(Context ctx) {
249	        try {
250	            String cpf = ctx.pathParam("cpf");
251	            Customer customer = customerRepository.findByCpf(cpf);
252	
253	            if (customer == null) {
254	                ctx.status(404).json(new ErrorResponseDto("CUSTOMER_NOT_FOUND"));
255	                return;
256	            }
257	
258	            CustomerResponseDto dto = new CustomerResponseDto();
259	            dto.cpf = customer.getCpf();
260	            dto.creditBalance = customer.getCreditBalance().toDouble();
261	
262	            ctx.status(200).json(dto);
263	
264	        } catch (Exception e) {
265	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
266	        }
267	    }
268	
269	    private void getNotifications(Context ctx) {
270	        try {
271	            String cpf = ctx.pathParam("cpf");
272	
273	            if (!customerRepository.exists(cpf)) {
274	                ctx.status(404).json(new ErrorResponseDto("CUSTOMER_NOT_FOUND"));
275	                return;
276	            }
277	
278	            List<Notification> notifications = notificationRepository.findByCustomerCpf(cpf);
279	            List<NotificationResponseDto> dtos = notifications.stream()
280	                    .map(n -> {
281	                        NotificationResponseDto dto = new NotificationResponseDto();
282	                        dto.id = n.getId();
283	                        dto.type = n.getType().name();
284	                        dto.orderId = n.getOrderId();
285	                        dto.status = n.getStatus().name();
286	                        return dto;
287	                    })
288	                    .collect(Collectors.toList());
289	
290	            ctx.status(200).json(dtos);
291	
292	        } catch (Exception e) {
293	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
294	        }
295	    }
296	
297	    private void markNotificationAsRead(Context ctx) {
298	        try {
299	            long notificationId = Long.parseLong(ctx.pathParam("id"));
300	            Notification notification = notificationRepository.findById(notificationId);
301	
302	            if (notification == null) {
303	                ctx.status(404).json(new ErrorResponseDto("NOTIFICATION_NOT_FOUND"));
304	                return;
305	            }
306	
307	            notification.markAsRead();
308	            notificationRepository.update(notification);
309	
310	            NotificationResponseDto dto = new NotificationResponseDto();
311	            dto.id = notification.getId();
312	            dto.type = notification.getType().name();
313	            dto.orderId = notification.getOrderId();
314	            dto.status = notification.getStatus().name();
315	
316	            ctx.status(200).json(dto);
317	
318	        } catch (NumberFormatException e) {
319	            ctx.status(404).json(new ErrorResponseDto("NOTIFICATION_NOT_FOUND"));
320	        } catch (Exception e) {
321	            ctx.status(500).json(new ErrorResponseDto("INTERNAL_ERROR"));
322	        }
323	    }
324	
325	    private CheckoutService.CheckoutRequest parseCheckoutRequest(CheckoutRequestDto dto) {
326	        List<OrderItem> items = dto.items.stream()
327	                .map(i -> new OrderItem(i.sku, i.quantity))
328	                .collect(Collectors.toList());
329	
330	        return new CheckoutService.CheckoutRequest(
331	                dto.customer.cpf,
332	                items,
333	                dto.zipCode,
334	                dto.region != null ? Region.valueOf(dto.region) : null,
335	                dto.shippingMethod != null ? ShippingMethod.valueOf(dto.shippingMethod) : null,
336	                dto.coupon != null && !dto.coupon.isBlank() ? CouponCode.valueOf(dto.coupon) : null,
337	                dto.paymentMethod != null ? PaymentMethod.valueOf(dto.paymentMethod) : null,
338	                dto.installments != null ? dto.installments : 1,
339	                dto.clubTier != null ? ClubTier.valueOf(dto.clubTier) : null
340	        );
341	    }
342	
343	    private SummaryResponseDto toSummaryDto(OrderSummary summary) {
344	        SummaryResponseDto dto = new SummaryResponseDto();
345	        dto.productsSubtotal = summary.getProductsSubtotal().toDouble();
346	        dto.couponDiscount = summary.getCouponDiscount().toDouble();
347	        dto.shippingCost = summary.getShippingCost().toDouble();
348	        dto.deliveryDays = summary.getDeliveryDays();
349	        dto.insurance = summary.getInsurance().toDouble();
350	        dto.paymentAdjustment = summary.getPaymentAdjustment().toDouble();
351	        dto.finalTotal = summary.getFinalTotal().toDouble();
352	        dto.installments = summary.getInstallments();
353	        dto.installmentAmount = summary.getInstallmentAmount().toDouble();
354	        dto.nextPurchaseCredit = summary.getNextPurchaseCredit().toDouble();
355	        dto.gift = summary.isGift();
356	        return dto;
357	    }
358	
359	    private OrderResponseDto toOrderDto(Order order) {
360	        OrderResponseDto dto = new OrderResponseDto();
361	        dto.id = order.getId();
362	        dto.status = order.getStatus().name();
363	        dto.createdAt = DateTimeFormatter.ISO_INSTANT.format(order.getCreatedAt());
364	        dto.summary = toSummaryDto(order.getSummary());
365	        dto.items = order.getItems().stream()
366	                .map(i -> {
367	                    OrderResponseDto.OrderItemResponseDto itemDto = new OrderResponseDto.OrderItemResponseDto();
368	                    itemDto.sku = i.getSku();
369	                    itemDto.quantity = i.getQuantity();
370	                    return itemDto;
371	                })
372	                .collect(Collectors.toList());
373	        dto.trackingCode = order.getTrackingCode();
374	        return dto;
375	    }
376	
377	    private void handleValidationError(Context ctx, ValidationService.ValidationException e) {
378	        int status = switch (e.getErrorCode()) {
379	            case "CARRIER_UNAVAILABLE" -> 503;
380	            default -> 422;
381	        };
382	        ctx.status(status).json(new ErrorResponseDto(e.getErrorCode()));
383	    }
384	}

