  1	package com.loja.services;
  2	
  3	import com.loja.domain.entities.*;
  4	import com.loja.domain.strategies.club.ClubTierStrategy;
  5	import com.loja.domain.strategies.coupon.CouponStrategy;
  6	import com.loja.domain.strategies.payment.PaymentMethodStrategy;
  7	import com.loja.domain.strategies.shipping.ShippingStrategy;
  8	import com.loja.domain.strategies.shipping.ShippingUnavailableException;
  9	import com.loja.repositories.ProductRepository;
 10	
 11	import java.util.List;
 12	import java.util.Map;
 13	
 14	public class CheckoutService {
 15	    private static final double MAX_COUPON_DISCOUNT_PERCENT = 0.30;
 16	
 17	    private final ProductRepository productRepository;
 18	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
 19	    private final Map<CouponCode, CouponStrategy> couponStrategies;
 20	    private final Map<ClubTier, ClubTierStrategy> clubTierStrategies;
 21	    private final Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies;
 22	
 23	    public CheckoutService(
 24	            ProductRepository productRepository,
 25	            Map<ShippingMethod, ShippingStrategy> shippingStrategies,
 26	            Map<CouponCode, CouponStrategy> couponStrategies,
 27	            Map<ClubTier, ClubTierStrategy> clubTierStrategies,
 28	            Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies) {
 29	        this.productRepository = productRepository;
 30	        this.shippingStrategies = shippingStrategies;
 31	        this.couponStrategies = couponStrategies;
 32	        this.clubTierStrategies = clubTierStrategies;
 33	        this.paymentMethodStrategies = paymentMethodStrategies;
 34	    }
 35	
 36	    public OrderSummary calculateSummary(CheckoutRequest request) throws ShippingUnavailableException {
 37	        Money productsSubtotal = calculateProductsSubtotal(request.items());
 38	
 39	        ShippingStrategy shippingStrategy = shippingStrategies.get(request.shippingMethod());
 40	        Money rawShippingCost = shippingStrategy.calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
 41	        int baseDeliveryDays = shippingStrategy.calculateDeliveryDays(request.region());
 42	
 43	        CouponStrategy couponStrategy = request.coupon() != null ? couponStrategies.get(request.coupon()) : null;
 44	        Money couponDiscount = Money.zero();
 45	        if (couponStrategy != null) {
 46	            couponDiscount = couponStrategy.calculateDiscount(
 47	                    productsSubtotal,
 48	                    rawShippingCost,
 49	                    request.items(),
 50	                    request.customerCpf()
 51	            );
 52	            Money maxDiscount = productsSubtotal.multiply(MAX_COUPON_DISCOUNT_PERCENT);
 53	            if (couponDiscount.isGreaterThan(maxDiscount)) {
 54	                couponDiscount = maxDiscount;
 55	            }
 56	        }
 57	
 58	        Money insurance = calculateInsurance(productsSubtotal, request.region());
 59	
 60	        ClubTierStrategy clubStrategy = clubTierStrategies.get(request.clubTier());
 61	        Money adjustedShippingCost = clubStrategy.adjustShippingCost(rawShippingCost, request.shippingMethod());
 62	
 63	        Money orderTotal = productsSubtotal
 64	                .subtract(couponDiscount)
 65	                .add(adjustedShippingCost)
 66	                .add(insurance);
 67	
 68	        PaymentMethodStrategy paymentStrategy = paymentMethodStrategies.get(request.paymentMethod());
 69	        int installments = paymentStrategy.calculateInstallments(request.installments());
 70	        Money paymentAdjustment = paymentStrategy.calculateAdjustment(
 71	                orderTotal,
 72	                installments,
 73	                request.coupon() != null
 74	        );
 75	
 76	        Money finalTotal = orderTotal.add(paymentAdjustment);
 77	        Money installmentAmount = paymentStrategy.calculateInstallmentAmount(finalTotal, installments);
 78	
 79	        Money nextPurchaseCredit = clubStrategy.calculateCredit(productsSubtotal);
 80	        boolean gift = clubStrategy.hasGift(productsSubtotal);
 81	
 82	        return new OrderSummary(
 83	                productsSubtotal,
 84	                couponDiscount,
 85	                adjustedShippingCost,
 86	                baseDeliveryDays,
 87	                insurance,
 88	                paymentAdjustment,
 89	                finalTotal,
 90	                installments,
 91	                installmentAmount,
 92	                nextPurchaseCredit,
 93	                gift
 94	        );
 95	    }
 96	
 97	    private Money calculateProductsSubtotal(List<OrderItem> items) {
 98	        Money subtotal = Money.zero();
 99	        for (OrderItem item : items) {
100	            Product product = productRepository.findBySku(item.getSku());
101	            Money itemTotal = product.getPrice().multiply(item.getQuantity());
102	            subtotal = subtotal.add(itemTotal);
103	        }
104	        return subtotal;
105	    }
106	
107	    private double calculateTotalWeight(List<OrderItem> items) {
108	        double totalWeight = 0;
109	        for (OrderItem item : items) {
110	            Product product = productRepository.findBySku(item.getSku());
111	            totalWeight += product.getWeightKg() * item.getQuantity();
112	        }
113	        return totalWeight;
114	    }
115	
116	    private Money calculateInsurance(Money productsSubtotal, Region region) {
117	        double percentage = switch (region) {
118	            case SOUTHEAST, SOUTH -> 0.01;
119	            case MIDWEST -> 0.015;
120	            case NORTHEAST -> 0.02;
121	            case NORTH -> 0.025;
122	        };
123	
124	        Money insurance = productsSubtotal.multiply(percentage);
125	
126	        Money limit = switch (region) {
127	            case NORTH, NORTHEAST -> Money.of(30.00);
128	            case SOUTHEAST, SOUTH, MIDWEST -> null;
129	        };
130	
131	        if (limit != null && insurance.isGreaterThan(limit)) {
132	            return limit;
133	        }
134	
135	        return insurance;
136	    }
137	
138	    public record CheckoutRequest(
139	            String customerCpf,
140	            List<OrderItem> items,
141	            String zipCode,
142	            Region region,
143	            ShippingMethod shippingMethod,
144	            CouponCode coupon,
145	            PaymentMethod paymentMethod,
146	            int installments,
147	            ClubTier clubTier
148	    ) {
149	    }
150	}
151	package com.loja.services;
152	
153	import com.loja.domain.entities.*;
154	import com.loja.domain.events.PaymentConfirmedEvent;
155	import com.loja.domain.observers.PaymentConfirmedObserver;
156	import com.loja.domain.observers.StockObserver;
157	import com.loja.repositories.CustomerRepository;
158	import com.loja.repositories.NotificationRepository;
159	import com.loja.repositories.OrderRepository;
160	import com.loja.repositories.ProductRepository;
161	import com.loja.repositories.impl.OrderRepositoryImpl;
162	
163	import java.time.Instant;
164	import java.util.ArrayList;
165	import java.util.List;
166	import java.util.UUID;
167	
168	public class OrderService {
169	    private final OrderRepository orderRepository;
170	    private final CustomerRepository customerRepository;
171	    private final NotificationRepository notificationRepository;
172	    private final ProductRepository productRepository;
173	    private final List<PaymentConfirmedObserver> paymentObservers;
174	
175	    public OrderService(
176	            OrderRepository orderRepository,
177	            CustomerRepository customerRepository,
178	            NotificationRepository notificationRepository,
179	            ProductRepository productRepository,
180	            List<PaymentConfirmedObserver> paymentObservers) {
181	        this.orderRepository = orderRepository;
182	        this.customerRepository = customerRepository;
183	        this.notificationRepository = notificationRepository;
184	        this.productRepository = productRepository;
185	        this.paymentObservers = paymentObservers;
186	    }
187	
188	    public Order createOrder(String customerCpf, String customerEmail, List<OrderItem> items, OrderSummary summary) {
189	        if (!customerRepository.exists(customerCpf)) {
190	            Customer customer = new Customer(customerCpf);
191	            customerRepository.save(customer);
192	        }
193	
194	        String orderId = UUID.randomUUID().toString();
195	        Order order = new Order(
196	                orderId,
197	                customerCpf,
198	                customerEmail,
199	                items,
200	                summary,
201	                OrderStatus.AWAITING_PAYMENT,
202	                Instant.now()
203	        );
204	
205	        orderRepository.save(order);
206	        return order;
207	    }
208	
209	    public Order confirmPayment(String orderId, String transactionId, Instant paidAt) throws PaymentException {
210	        Order order = orderRepository.findById(orderId);
211	        if (order == null) {
212	            throw new PaymentException("Order not found");
213	        }
214	
215	        if (orderRepository.hasPaymentTransaction(orderId, transactionId)) {
216	            return order;
217	        }
218	
219	        if (!order.canBePaid()) {
220	            throw new PaymentException("Order cannot be paid in current status: " + order.getStatus());
221	        }
222	
223	        if (order.isExpired(paidAt)) {
224	            order.cancel();
225	            orderRepository.update(order);
226	            ((OrderRepositoryImpl) orderRepository).savePaymentTransaction(orderId, transactionId);
227	
228	            notifyCustomerCancellation(order);
229	
230	            throw new OrderExpiredException("Order expired");
231	        }
232	
233	        try {
234	            notifyPaymentConfirmed(order);
235	
236	            order.confirmPayment(transactionId, paidAt);
237	            orderRepository.update(order);
238	            ((OrderRepositoryImpl) orderRepository).savePaymentTransaction(orderId, transactionId);
239	
240	            return order;
241	
242	        } catch (StockObserver.InsufficientStockException e) {
243	            order.cancel();
244	            orderRepository.update(order);
245	            ((OrderRepositoryImpl) orderRepository).savePaymentTransaction(orderId, transactionId);
246	
247	            notifyCustomerCancellation(order);
248	
249	            throw new InsufficientStockException("Insufficient stock");
250	        } catch (Exception e) {
251	            throw new PaymentException("Failed to confirm payment", e);
252	        }
253	    }
254	
255	    public Order shipOrder(String orderId, String trackingCode) throws ShipmentException {
256	        Order order = orderRepository.findById(orderId);
257	        if (order == null) {
258	            throw new ShipmentException("Order not found");
259	        }
260	
261	        if (!order.canBeShipped()) {
262	            throw new ShipmentException("Order cannot be shipped in current status: " + order.getStatus());
263	        }
264	
265	        order.ship(trackingCode);
266	        orderRepository.update(order);
267	
268	        notifyCustomerShipment(order);
269	
270	        return order;
271	    }
272	
273	    public Order deliverOrder(String orderId) throws DeliveryException {
274	        Order order = orderRepository.findById(orderId);
275	        if (order == null) {
276	            throw new DeliveryException("Order not found");
277	        }
278	
279	        if (!order.canBeDelivered()) {
280	            throw new DeliveryException("Order cannot be delivered in current status: " + order.getStatus());
281	        }
282	
283	        order.deliver();
284	        orderRepository.update(order);
285	
286	        return order;
287	    }
288	
289	    public Order cancelOrder(String orderId) throws CancellationException {
290	        Order order = orderRepository.findById(orderId);
291	        if (order == null) {
292	            throw new CancellationException("Order not found");
293	        }
294	
295	        if (!order.canBeCancelled()) {
296	            throw new CancellationException("Order cannot be cancelled in current status: " + order.getStatus());
297	        }
298	
299	        boolean wasPaid = order.getStatus() == OrderStatus.PAID;
300	
301	        order.cancel();
302	        orderRepository.update(order);
303	
304	        if (wasPaid) {
305	            reversePaymentEffects(order);
306	        }
307	
308	        notifyCustomerCancellation(order);
309	
310	        return order;
311	    }
312	
313	    private void notifyPaymentConfirmed(Order order) throws Exception {
314	        PaymentConfirmedEvent event = new PaymentConfirmedEvent(order);
315	
316	        for (PaymentConfirmedObserver observer : paymentObservers) {
317	            observer.onPaymentConfirmed(event);
318	        }
319	    }
320	
321	    private void reversePaymentEffects(Order order) {
322	        for (OrderItem item : order.getItems()) {
323	            Product product = productRepository.findBySku(item.getSku());
324	            product.increaseStock(item.getQuantity());
325	            productRepository.update(product);
326	        }
327	
328	        Money creditAmount = order.getSummary().getNextPurchaseCredit();
329	        if (creditAmount.isPositive()) {
330	            Customer customer = customerRepository.findByCpf(order.getCustomerCpf());
331	            customer.subtractCredit(creditAmount);
332	            customerRepository.update(customer);
333	        }
334	    }
335	
336	    private void notifyCustomerShipment(Order order) {
337	        Notification notification = new Notification(
338	                0,
339	                NotificationType.ORDER_SHIPPED,
340	                order.getId(),
341	                NotificationStatus.NEW
342	        );
343	        notificationRepository.save(order.getCustomerCpf(), notification);
344	    }
345	
346	    private void notifyCustomerCancellation(Order order) {
347	        Notification notification = new Notification(
348	                0,
349	                NotificationType.ORDER_CANCELLED,
350	                order.getId(),
351	                NotificationStatus.NEW
352	        );
353	        notificationRepository.save(order.getCustomerCpf(), notification);
354	    }
355	
356	    public static class PaymentException extends Exception {
357	        public PaymentException(String message) {
358	            super(message);
359	        }
360	
361	        public PaymentException(String message, Throwable cause) {
362	            super(message, cause);
363	        }
364	    }
365	
366	    public static class OrderExpiredException extends PaymentException {
367	        public OrderExpiredException(String message) {
368	            super(message);
369	        }
370	    }
371	
372	    public static class InsufficientStockException extends PaymentException {
373	        public InsufficientStockException(String message) {
374	            super(message);
375	        }
376	    }
377	
378	    public static class ShipmentException extends Exception {
379	        public ShipmentException(String message) {
380	            super(message);
381	        }
382	    }
383	
384	    public static class DeliveryException extends Exception {
385	        public DeliveryException(String message) {
386	            super(message);
387	        }
388	    }
389	
390	    public static class CancellationException extends Exception {
391	        public CancellationException(String message) {
392	            super(message);
393	        }
394	    }
395	}
396	package com.loja.services;
397	
398	import com.loja.domain.entities.*;
399	import com.loja.domain.strategies.coupon.CouponStrategy;
400	import com.loja.domain.strategies.payment.PaymentMethodStrategy;
401	import com.loja.domain.strategies.shipping.ShippingStrategy;
402	import com.loja.repositories.OrderRepository;
403	import com.loja.repositories.ProductRepository;
404	
405	import java.util.HashSet;
406	import java.util.List;
407	import java.util.Map;
408	import java.util.Set;
409	
410	public class ValidationService {
411	    private final ProductRepository productRepository;
412	    private final OrderRepository orderRepository;
413	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
414	    private final Map<CouponCode, CouponStrategy> couponStrategies;
415	    private final Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies;
416	
417	    public ValidationService(
418	            ProductRepository productRepository,
419	            OrderRepository orderRepository,
420	            Map<ShippingMethod, ShippingStrategy> shippingStrategies,
421	            Map<CouponCode, CouponStrategy> couponStrategies,
422	            Map<PaymentMethod, PaymentMethodStrategy> paymentMethodStrategies) {
423	        this.productRepository = productRepository;
424	        this.orderRepository = orderRepository;
425	        this.shippingStrategies = shippingStrategies;
426	        this.couponStrategies = couponStrategies;
427	        this.paymentMethodStrategies = paymentMethodStrategies;
428	    }
429	
430	    public void validateCheckoutRequest(CheckoutService.CheckoutRequest request) throws ValidationException {
431	        validateOrderStructure(request);
432	        validateProducts(request.items());
433	        validateClubTier(request.clubTier());
434	        validateRegion(request.region());
435	        validateZipCode(request.zipCode());
436	        validateShippingMethod(request.shippingMethod(), request.items(), request.zipCode());
437	        validateCoupon(request);
438	        validatePaymentMethod(request);
439	    }
440	
441	    private void validateOrderStructure(CheckoutService.CheckoutRequest request) throws ValidationException {
442	        if (request.items() == null || request.items().isEmpty()) {
443	            throw new ValidationException("INVALID_ORDER", "Cart is empty");
444	        }
445	
446	        if (request.customerCpf() == null || request.customerCpf().isBlank()) {
447	            throw new ValidationException("INVALID_ORDER", "Customer CPF is required");
448	        }
449	
450	        Set<String> skus = new HashSet<>();
451	        for (OrderItem item : request.items()) {
452	            if (item.getSku() == null || item.getSku().isBlank()) {
453	                throw new ValidationException("INVALID_ORDER", "Item SKU is required");
454	            }
455	
456	            if (item.getQuantity() <= 0) {
457	                throw new ValidationException("INVALID_ORDER", "Item quantity must be positive");
458	            }
459	
460	            if (skus.contains(item.getSku())) {
461	                throw new ValidationException("INVALID_ORDER", "Duplicate SKU in cart: " + item.getSku());
462	            }
463	            skus.add(item.getSku());
464	        }
465	    }
466	
467	    private void validateProducts(List<OrderItem> items) throws ValidationException {
468	        for (OrderItem item : items) {
469	            Product product = productRepository.findBySku(item.getSku());
470	
471	            if (product == null) {
