 36	    public OrderSummary calculateSummary(CheckoutRequest request) throws ShippingUnavailableException {
 37	        Money productsSubtotal = calculateProductsSubtotal(request.items());
 38	
 39	        ShippingStrategy shippingStrategy = shippingStrategies.get(request.shippingMethod());
 40	        Money rawShippingCost = shippingStrategy.calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
 41	        int baseDeliveryDays = shippingStrategy.calculateDeliveryDays(request.region());
 42	
 43	        CouponStrategy couponStrategy = request.coupon() != null ? couponStrategies.get(request.coupon()) : null;
 44	        Money couponDiscount = Money.zero();
 45	        if (couponStrategy != null) {
 46	            couponDiscount = couponStrategy.calculateDiscount(
 47	                    productsSubtotal,
 48	                    rawShippingCost,
 49	                    request.items(),
 50	                    request.customerCpf()
 51	            );
 52	            Money maxDiscount = productsSubtotal.multiply(MAX_COUPON_DISCOUNT_PERCENT);
 53	            if (couponDiscount.isGreaterThan(maxDiscount)) {
 54	                couponDiscount = maxDiscount;
 55	            }
 56	        }
 57	
 58	        Money insurance = calculateInsurance(productsSubtotal, request.region());
 59	
 60	        ClubTierStrategy clubStrategy = clubTierStrategies.get(request.clubTier());
 61	        Money adjustedShippingCost = clubStrategy.adjustShippingCost(rawShippingCost, request.shippingMethod());
 62	
