210	        Order order = orderRepository.findById(orderId);
211	        if (order == null) {
212	            throw new PaymentException("Order not found");
213	        }
214	
215	        if (orderRepository.hasPaymentTransaction(orderId, transactionId)) {
216	            return order;
217	        }
218	
219	        if (!order.canBePaid()) {
220	            throw new PaymentException("Order cannot be paid in current status: " + order.getStatus());
221	        }
222	
223	        if (order.isExpired(paidAt)) {
224	            order.cancel();
225	            orderRepository.update(order);
