514	
515	        try {
516	            Money cost = strategy.calculateCost(zipCode, totalWeight);
517	            if (!strategy.isAvailable(totalWeight, zipCode)) {
518	                throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE", "Shipping method not available");
519	            }
520	        } catch (Exception e) {
521	            if (e.getMessage() != null && e.getMessage().contains("unavailable")) {
522	                throw new ValidationException("CARRIER_UNAVAILABLE", "Carrier unavailable");
523	            }
524	            if (e.getMessage() != null && e.getMessage().contains("not served")) {
525	                throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE", "Shipping method not available for this location");
526	            }
527	            throw new ValidationException("CARRIER_UNAVAILABLE", "Carrier unavailable");
528	        }
529	    }
530	
531	    private void validateCoupon(CheckoutService.CheckoutRequest request) throws ValidationException {
532	        if (request.coupon() == null) {
533	            return;
534	        }
535	
536	        CouponStrategy strategy = couponStrategies.get(request.coupon());
537	        if (strategy == null) {
538	            throw new ValidationException("INVALID_COUPON", "Invalid coupon code");
539	        }
540	
541	        Money productsSubtotal = calculateProductsSubtotal(request.items());
542	        Money shippingCost = Money.zero();
543	        try {
544	            shippingCost = shippingStrategies.get(request.shippingMethod())
545	                    .calculateCost(request.zipCode(), calculateTotalWeight(request.items()));
546	        } catch (Exception e) {
547	        }
548	
549	        if (!strategy.isApplicable(
550	                productsSubtotal,
551	                shippingCost,
552	                request.items(),
553	                request.customerCpf(),
554	                request.shippingMethod())) {
555	            throw new ValidationException("COUPON_NOT_APPLICABLE", "Coupon not applicable to this order");
556	        }
557	    }
558	
559	    private void validatePaymentMethod(CheckoutService.CheckoutRequest request) throws ValidationException {
560	        if (request.paymentMethod() == null) {
561	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Payment method is required");
562	        }
563	
564	        PaymentMethodStrategy strategy = paymentMethodStrategies.get(request.paymentMethod());
565	        if (strategy == null) {
566	            throw new ValidationException("INVALID_PAYMENT_METHOD", "Invalid payment method");
567	        }
568	
569	        int installments = request.installments();
570	        if (request.paymentMethod() == PaymentMethod.PIX || request.paymentMethod() == PaymentMethod.BANK_SLIP) {
571	            if (installments != 1 && installments != 0) {
572	                throw new ValidationException("INVALID_INSTALLMENTS", "PIX and bank slip must be paid in full");
573	            }
574	        } else if (request.paymentMethod() == PaymentMethod.CREDIT_CARD) {
575	            if (installments < 1 || installments > 12) {
576	                throw new ValidationException("INVALID_INSTALLMENTS", "Credit card installments must be between 1 and 12");
577	            }
578	        }
579	
580	        Money productsSubtotal = calculateProductsSubtotal(request.items());
581	        if (!strategy.isAvailable(productsSubtotal)) {
582	            throw new ValidationException("PAYMENT_METHOD_UNAVAILABLE", "Payment method not available for this order total");
583	        }
584	    }
585	
586	    private Money calculateProductsSubtotal(List<OrderItem> items) {
587	        Money subtotal = Money.zero();
588	        for (OrderItem item : items) {
589	            Product product = productRepository.findBySku(item.getSku());
590	            subtotal = subtotal.add(product.getPrice().multiply(item.getQuantity()));
591	        }
592	        return subtotal;
593	    }
594	
595	    private double calculateTotalWeight(List<OrderItem> items) {
596	        double totalWeight = 0;
597	        for (OrderItem item : items) {
598	            Product product = productRepository.findBySku(item.getSku());
599	            totalWeight += product.getWeightKg() * item.getQuantity();
600	        }
601	        return totalWeight;
602	    }
603	
604	    public static class ValidationException extends Exception {
605	        private final String errorCode;
606	
607	        public ValidationException(String errorCode, String message) {
608	            super(message);
609	            this.errorCode = errorCode;
610	        }
611	
612	        public String getErrorCode() {
613	            return errorCode;
614	        }
615	    }
616	}

