189	public class StockObserver implements PaymentConfirmedObserver {
190	    private final ProductRepository productRepository;
191	
192	    public StockObserver(ProductRepository productRepository) {
193	        this.productRepository = productRepository;
194	    }
195	
196	    @Override
197	    public void onPaymentConfirmed(PaymentConfirmedEvent event) throws Exception {
198	        Order order = event.getOrder();
199	
200	        for (OrderItem item : order.getItems()) {
201	            Product product = productRepository.findBySku(item.getSku());
202	            if (!product.hasStock(item.getQuantity())) {
203	                throw new InsufficientStockException("Insufficient stock for product " + item.getSku());
204	            }
