464	    }
465	
466	    public boolean isExpired(Instant now) {
467	        long hoursSinceCreation = (now.toEpochMilli() - createdAt.toEpochMilli()) / 1000 / 3600;
468	        return hoursSinceCreation > 48;
469	    }
470	
471	    public void confirmPayment(String transactionId, Instant paidAt) {
472	        this.paymentTransactionId = transactionId;
473	        this.paidAt = paidAt;
474	        this.status = OrderStatus.PAID;
475	    }
476	
477	    public void ship(String trackingCode) {
478	        this.trackingCode = trackingCode;
479	        this.status = OrderStatus.SHIPPED;
480	    }
481	
482	    public void deliver() {
483	        this.status = OrderStatus.DELIVERED;
484	    }
485	
486	    public void cancel() {
487	        this.status = OrderStatus.CANCELLED;
488	    }
489	
490	    public boolean canBePaid() {
491	        return status == OrderStatus.AWAITING_PAYMENT;
492	    }
493	
494	    public boolean canBeShipped() {
495	        return status == OrderStatus.PAID;
496	    }
497	
498	    public boolean canBeDelivered() {
499	        return status == OrderStatus.SHIPPED;
500	    }
501	
502	    public boolean canBeCancelled() {
503	        return status == OrderStatus.AWAITING_PAYMENT || status == OrderStatus.PAID;
504	    }
