229	public class Buy3Pay2Coupon implements CouponStrategy {
230	    private final ProductRepository productRepository;
231	
232	    public Buy3Pay2Coupon(ProductRepository productRepository) {
233	        this.productRepository = productRepository;
234	    }
235	
236	    @Override
237	    public Money calculateDiscount(Money productsSubtotal, Money shippingCost, List<OrderItem> items, String customerCpf) {
238	        Money totalDiscount = Money.zero();
239	
240	        Map<String, Integer> quantitiesBySku = items.stream()
241	                .collect(Collectors.toMap(OrderItem::getSku, OrderItem::getQuantity));
242	
243	        for (Map.Entry<String, Integer> entry : quantitiesBySku.entrySet()) {
244	            String sku = entry.getKey();
245	            int quantity = entry.getValue();
246	
247	            if (quantity >= 3) {
248	                int freeUnits = quantity / 3;
249	                Product product = productRepository.findBySku(sku);
250	                Money unitPrice = product.getPrice();
251	                Money discountForSku = unitPrice.multiply(freeUnits);
252	                totalDiscount = totalDiscount.add(discountForSku);
253	            }
254	        }
255	
256	        return totalDiscount;
257	    }
258	
259	    @Override
260	    public boolean isApplicable(Money productsSubtotal, Money shippingCost, List<OrderItem> items, String customerCpf, ShippingMethod shippingMethod) {
261	        return true;
262	    }
263	
264	    @Override
265	    public CouponCode getCode() {
266	        return CouponCode.BUY3PAY2;
267	    }
