   111	
   112	public class ExpressShipping implements ShippingStrategy {
   113	    private final TransLogClient transLogClient;
   114	
   115	    public ExpressShipping(TransLogClient transLogClient) {
   116	        this.transLogClient = transLogClient;
   117	    }
   118	
   119	    @Override
   120	    public Money calculateCost(String zipCode, double weightKg) throws ShippingUnavailableException {
   121	        try {
   122	            TransLogClient.TransLogQuote quote = transLogClient.getQuote(
   123	                    zipCode, weightKg, TransLogClient.TransLogService.EXPRESS);
   124	            return Money.of(quote.getPriceReais());
   125	        } catch (TransLogClient.ZipNotServedException e) {
   126	            throw new ShippingUnavailableException("ZIP not served", e);
   127	        } catch (TransLogClient.TransLogException e) {
   128	            throw new ShippingUnavailableException("Carrier unavailable", e);
   129	        }
   130	    }
   131	
   132	    @Override
   133	    public int calculateDeliveryDays(Region region) {
   134	        try {
   135	            TransLogClient.TransLogQuote quote = transLogClient.getQuote(
   136	                    "00000000", 1.0, TransLogClient.TransLogService.EXPRESS);
   137	            int baseDays = quote.getDeliveryDays();
   138	            return baseDays + getRegionalDelay(region);
   139	        } catch (Exception e) {
   140	            return 2 + getRegionalDelay(region);
   141	        }
   142	    }
   143	
   144	    private int getRegionalDelay(Region region) {
   145	        return switch (region) {
   146	            case NORTH -> 3;
   147	            case NORTHEAST -> 2;
   148	            default -> 0;
   149	        };
   150	    }
   151	
   152	    @Override
   153	    public boolean isAvailable(double weightKg, String zipCode) {
   154	        try {
   155	            calculateCost(zipCode, weightKg);
   156	            return true;
   157	        } catch (ShippingUnavailableException e) {
   158	            return false;
   159	        }
   160	    }
   161	
   162	    @Override
   163	    public ShippingMethod getMethod() {
   164	        return ShippingMethod.EXPRESS;
   165	    }
   166	}
