   252	public class CreditCardPayment implements PaymentMethodStrategy {
   253	    private static final double MONTHLY_INTEREST_RATE = 0.0199;
   254	    private static final int MAX_INSTALLMENTS_NO_INTEREST = 3;
   255	    private static final int MAX_INSTALLMENTS = 12;
   256	
   257	    @Override
   258	    public Money calculateAdjustment(Money orderTotal, int installments, boolean hasCoupon) {
   259	        if (installments <= MAX_INSTALLMENTS_NO_INTEREST) {
   260	            return Money.zero();
   261	        }
   262	
   263	        Money installmentAmount = calculateInstallmentWithInterest(orderTotal, installments);
   264	        Money finalTotal = installmentAmount.multiply(installments);
   265	        return finalTotal.subtract(orderTotal);
   266	    }
   267	
   268	    @Override
   269	    public int calculateInstallments(int requestedInstallments) {
   270	        if (requestedInstallments < 1) {
   271	            return 1;
   272	        }
