   284	    private Money calculateInstallmentWithInterest(Money principal, int installments) {
   285	        BigDecimal rate = BigDecimal.valueOf(MONTHLY_INTEREST_RATE);
   286	        BigDecimal numInstallments = BigDecimal.valueOf(installments);
   287	
   288	        BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
   289	        BigDecimal denominator = BigDecimal.ONE.subtract(
   290	                onePlusRate.pow(-installments, new java.math.MathContext(10, RoundingMode.HALF_EVEN))
   291	        );
   292	
   293	        BigDecimal installment = principal.toBigDecimal()
   294	                .multiply(rate)
   295	                .divide(denominator, 2, RoundingMode.HALF_EVEN);
   296	
   297	        return Money.of(installment);
   298	    }
